const listFeishuOrgTeamIDsForMember = `-- name: ListFeishuOrgTeamIDsForMember :many
SELECT fom.group_id
FROM feishu_org_membership fom
JOIN feishu_org_group fog
  ON fog.id = fom.group_id
 AND fog.workspace_id = fom.workspace_id
JOIN member m
  ON m.workspace_id = fom.workspace_id
 AND m.user_id = fom.user_id
WHERE fom.workspace_id = $1
  AND fom.user_id = $2
  AND fom.active
  AND fog.active
  AND m.disabled_at IS NULL
ORDER BY fom.group_id
`

type ListFeishuOrgTeamIDsForMemberParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	UserID      pgtype.UUID `json:"user_id"`
}

